// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice Library for bytes operations.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/LibBytes.sol)
library LibBytes {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                          STRUCTS                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice A struct representing a storage container for bytes data.
    /// @dev The struct includes a single field `_spacer` of type `bytes32`, which can be used as a placeholder or spacer in storage.
    struct BytesStorage {
        bytes32 _spacer;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                 BYTES STORAGE OPERATIONS                   */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Sets the bytes data in the storage slot.
    ///
    /// Steps:
    /// 1. Load the length of the bytes data `s` into `n`.
    /// 2. Pack the length `n` with a prefix `0xff` and store it in `packed`.
    ///
    /// 3. If the length `n` is less than or equal to `0xfe`:
    ///    - Set `i` to `0x1f`.
    ///    - Pack the first 32 bytes of `s` with the length `n` and store it in `packed`.
    ///    - If the length `n` is less than or equal to `i`, break the loop.
    ///
    /// 4. Otherwise:
    ///    - Calculate the offset `o` as `s + 0x20`.
    ///    - Store the storage slot address in memory at `0x00`.
    ///    - Calculate the storage pointer `p` using `keccak256(0x00, 0x20)`.
    ///    - Store the bytes data in the storage slot in chunks of 32 bytes.
    ///    - Increment `i` by 32 bytes until all data is stored.
    ///
    /// 5. Store the packed data in the storage slot.
    function set(BytesStorage storage $, bytes memory s) internal {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(s)
            let packed := shl(8, n)
            // If the length `n` is less than or equal to `0xfe`.
            if iszero(gt(n, 0xfe)) {
                let i := 0x1f
                packed := or(packed, and(mload(add(s, 0x20)), shr(8, not(0))))
                if iszero(gt(n, i)) {
                    sstore($.slot, packed)
                    return
                }
                for {} 1 {} {
                    sstore(keccak256(0x00, 0x20), mload(add(s, add(i, 0x01))))
                    i := add(i, 0x20)
                    if iszero(lt(i, n)) { break }
                }
                sstore($.slot, packed)
                return
            }
            // If the length `n` is greater than `0xfe`.
            let o := add(s, 0x20)
            mstore(0x00, $.slot)
            let p := keccak256(0x00, 0x20)
            for { let i := 0 } 1 {} {
                sstore(add(p, div(i, 0x20)), mload(add(o, i)))
                i := add(i, 0x20)
                if iszero(lt(i, n)) { break }
            }
            sstore($.slot, or(packed, 0xff))
        }
    }

    /// @notice Sets the calldata for a BytesStorage struct.
    ///
    /// @dev This function uses low-level assembly to efficiently store the calldata.
    /// It handles the storage of the length and the actual data in a packed format.
    ///
    /// Steps:
    /// 1. Pack the length of the calldata with a specific mask (0xff).
    /// 2. If the length is less than or equal to 0xfe, store the length and the first 32 bytes of the calldata.
    /// 3. If the length is greater than 0xfe, store the data in chunks of 32 bytes using the storage slot.
    /// 4. Store the packed length and data in the storage slot.
    function setCalldata(BytesStorage storage $, bytes calldata s) internal {
        /// @solidity memory-safe-assembly
        assembly {
            let n := s.length
            let packed := shl(8, n)
            // If the length `n` is less than or equal to `0xfe`.
            if iszero(gt(n, 0xfe)) {
                // Copy the calldata to scratch space and mask.
                calldatacopy(0x00, s.offset, 0x20)
                packed := or(packed, and(mload(0x00), shr(8, not(0))))
                if iszero(gt(n, 0x1f)) {
                    sstore($.slot, packed)
                    return
                }
                let i := 0x1f
                for {} 1 {} {
                    calldatacopy(0x00, add(s.offset, add(i, 0x01)), 0x20)
                    sstore(keccak256(0x00, 0x20), mload(0x00))
                    i := add(i, 0x20)
                    if iszero(lt(i, n)) { break }
                }
                sstore($.slot, packed)
                return
            }
            // If the length `n` is greater than `0xfe`.
            mstore(0x00, $.slot)
            let p := keccak256(0x00, 0x20)
            for { let i := 0 } 1 {} {
                calldatacopy(0x00, add(s.offset, i), 0x20)
                sstore(add(p, div(i, 0x20)), mload(0x00))
                i := add(i, 0x20)
                if iszero(lt(i, n)) { break }
            }
            sstore($.slot, or(packed, 0xff))
        }
    }

    /// @notice Clears the storage of the BytesStorage struct by deleting the `_spacer` field.
    ///
